#include <Servo.h>

// Servo Pan Sweep
// Maps a potentiometer's position directly onto a servo's angle.

const int POT_PIN = A0;
const int SERVO_PIN = 9;

Servo panServo;

void setup() {
  panServo.attach(SERVO_PIN);
}

void loop() {
  int potValue = analogRead(POT_PIN);          // 0-1023
  int angle = map(potValue, 0, 1023, 0, 180);   // rescale to 0-180 degrees

  panServo.write(angle);
  delay(15); // gives the servo time to physically catch up between updates
}
